const rawLine = msg.payload.toString().trim();
const regex = /^\[TS:([\d.]+)\]\s+\[MGMT\]\[LEN:(\d+)\]\[CHAN:(\d+)\]\[RSSI:([-\d]+)\]\[INT_TEMP:([\d.]+)C\]\[DATA:([0-9A-F]+)\]/;
const match = rawLine.match(regex);

if (match) {
    // FIX: Explicitly mapped match array indices to restore data integrity
    const timestamp = parseFloat(match[1]);
    const length    = parseInt(match[2], 10);
    const channel   = parseInt(match[3], 10);
    const rssi      = parseInt(match[4], 10);
    const cpuTemp   = parseFloat(match[5]);
    const rawHex    = match[6]; // FIXED: Accessing the exact 6th regex hex data string group

    const subtypeHex = rawHex.substring(0, 2);
    let frameType = "UNKNOWN";

    switch (subtypeHex) {
        case "80": frameType = "BEACON"; break;
        case "40": frameType = "PROBE_REQ"; break;
        case "50": frameType = "PROBE_RESP"; break;
        case "A0": frameType = "DISASSOCIATION"; break;
        case "C0": frameType = "DEAUTHENTICATION"; break;
        case "D0": frameType = "ACTION_FRAME"; break;
        case "B0": frameType = "AUTHENTICATION"; break;
        case "00": 
        case "10": frameType = "ASSOCIATION_REQ"; break; 
    }

    let sourceMac = "00:00:00:00:00:00";
    let destMac = "00:00:00:00:00:00";
    if (rawHex.length >= 32) {
        destMac = rawHex.substring(8, 20).match(/.{1,2}/g).join(':');
        sourceMac = rawHex.substring(20, 32).match(/.{1,2}/g).join(':');
    }

    // -------------------------------------------------------------
    // HONEYPOT-AWARE SELF-HEALING TSF EXTRACTION ENGINE
    // -------------------------------------------------------------
    let ssid = "<HIDDEN NETWORK>";
    let encryption = "OPEN";
    let wps_status = "DISABLED";
    let tsf_microseconds = null;
    let apRebootString = null;
    let apUptimeCompact = null;

    let temp_wps_attrs = {};
    let isPairingDetected = false;

    if ((subtypeHex === "80" || subtypeHex === "50") && rawHex.length > 72) {
        let tsfStart = 48;
        let tsfEnd = 64;
        let ieStartIdx = 72;

        let totalSeconds = 0;
        let rebootEpochSeconds = 0;
        let bigIntVal = 0n;
        let isValidTSF = false;

        for (let pass = 0; pass < 3; pass++) {
            if (tsfEnd > rawHex.length) break;

            let tsfHex = rawHex.substring(tsfStart, tsfEnd);
            let leHex = tsfHex.match(/.{1,2}/g).reverse().join('');
            bigIntVal = BigInt("0x" + leHex);
            totalSeconds = Number(bigIntVal / 1000000n);
            rebootEpochSeconds = timestamp - totalSeconds;

            if (rebootEpochSeconds >= 0 && rebootEpochSeconds <= timestamp) {
                isValidTSF = true;
                break;
            }

            tsfStart += 8;
            tsfEnd += 8;
            ieStartIdx += 8;
        }

        if (isValidTSF) {
            tsf_microseconds = bigIntVal.toString();
            apRebootString = new Date(rebootEpochSeconds * 1000).toLocaleString(); 

            if (totalSeconds < 60) apUptimeCompact = `${totalSeconds}s`;
            else if (totalSeconds < 3600) apUptimeCompact = `${Math.floor(totalSeconds / 60)}m`;
            else if (totalSeconds < 86400) apUptimeCompact = `${Math.floor(totalSeconds / 3600)}h`;
            else apUptimeCompact = `${Math.floor(totalSeconds / 86400)}d`;
        } else {
            tsf_microseconds = "0";
            apRebootString = "Invalid";
            apUptimeCompact = "Invalid";
            ieStartIdx = 72; 
        }

        // Tagged Information Elements Loop
        let idx = ieStartIdx; 
        while (idx < rawHex.length - 4) {
            let tagId  = parseInt(rawHex.substring(idx, idx + 2), 16);
            let tagLen = parseInt(rawHex.substring(idx + 2, idx + 4), 16); 
            idx += 4; 

            let hexLen = tagLen * 2; 
            if (idx + hexLen > rawHex.length) break; 

            let tagData = rawHex.substring(idx, idx + hexLen);
            const upperTagData = tagData.toUpperCase();

            if (tagId === 0) {
                if (tagLen > 0) {
                    let ssidStr = "";
                    for (let i = 0; i < tagData.length; i += 2) {
                        let charCode = parseInt(tagData.substring(i, i + 2), 16);
                        if (charCode >= 32 && charCode <= 126) ssidStr += String.fromCharCode(charCode);
                    }
                    if (ssidStr.trim() !== "") ssid = ssidStr;
                }
            }
            else if (tagId === 48) {
                if (upperTagData.includes("000FAC12")) encryption = "OWE"; 
                else {
                    encryption = "WPA2";
                    if (upperTagData.includes("000FAC08") || upperTagData.includes("000FAC09")) encryption = "WPA3";
                    else if (upperTagData.includes("000FAC06")) encryption = "WPA2/WPA3-Transition";
                }
            }
            else if (tagId === 221) {
                if (upperTagData.startsWith("0050F201") && encryption === "OPEN") encryption = "WPA";
                else if (upperTagData.startsWith("0050F212")) encryption = "OWE";
                else if (upperTagData.startsWith("0050F204")) {
                    wps_status = "ENABLED";

                    let wIdx = 8; 
                    while (wIdx < upperTagData.length - 8) {
                        let attrId  = upperTagData.substring(wIdx, wIdx + 4);
                        let attrLen = parseInt(upperTagData.substring(wIdx + 4, wIdx + 8), 16) * 2;
                        wIdx += 8;

                        if (wIdx + attrLen > upperTagData.length) break;
                        let attrValue = upperTagData.substring(wIdx, wIdx + attrLen);

                        const hexToAscii = (hexStr) => {
                            let str = "";
                            for (let n = 0; n < hexStr.length; n += 2) {
                                let c = parseInt(hexStr.substring(n, n + 2), 16);
                                if (c >= 32 && c <= 126) str += String.fromCharCode(c);
                            }
                            return str.trim();
                        };

                        if (attrId === "1041" && attrValue === "01") {
                            isPairingDetected = true;
                        }

                        switch(attrId) {
                            case "1011": temp_wps_attrs.device_name = hexToAscii(attrValue); break;
                            case "1021": temp_wps_attrs.model_name  = hexToAscii(attrValue); break;
                            case "1023": temp_wps_attrs.model_number = hexToAscii(attrValue); break;
                            case "1024": temp_wps_attrs.serial_number = hexToAscii(attrValue); break;
                            case "1027": temp_wps_attrs.primary_device_type_hex = attrValue; break; 
                            case "1042": temp_wps_attrs.response_type_hex = attrValue; break; 
                        }
                        wIdx += attrLen;
                    }
                }
            }
            idx += hexLen; 
        }
    }

    if (wps_status === "ENABLED" && isPairingDetected) {
        wps_status = "PAIRING";
    }

    let outputPayload = {
        timestamp: timestamp,
        frame_type: frameType,
        subtype_hex: "0x" + subtypeHex,
        channel: channel,
        rssi: rssi,
        cpu_temperature_c: cpuTemp,
        tsf_microseconds: tsf_microseconds,
        ap_last_reboot_time: apRebootString, 
        ap_uptime_compact: apUptimeCompact, 
        packet_length_bytes: length,
        mac_source: sourceMac,
        mac_destination: destMac,
        ssid: ssid, 
        encryption: encryption,
        wps_status: wps_status,
        raw_data_hex: rawHex
    };

    if (Object.keys(temp_wps_attrs).length > 0) {
        outputPayload.wps_attributes = temp_wps_attrs;
    }

    msg.payload = outputPayload;
    return msg;
}
