const pkt = msg.payload;
const mac = pkt.mac_source;

const currentEpoch = pkt.timestamp;
const currentLocalStr = new Date(currentEpoch * 1000).toLocaleString();

if (!apDatabase[mac]) {
    apDatabase[mac] = {
        mac_source: mac,
        ssid: pkt.ssid,
        encryption: pkt.encryption,
        wps_status: pkt.wps_status,
        channel: pkt.channel,
        rssi_latest: pkt.rssi,
        cpu_temperature_latest_c: pkt.cpu_temperature_c,
        tsf_microseconds_latest: pkt.tsf_microseconds,
        ap_last_reboot_time: pkt.ap_last_reboot_time,
        ap_uptime_compact: pkt.ap_uptime_compact,
        packet_length_bytes: pkt.packet_length_bytes,
        first_seen_epoch: currentEpoch,
        first_seen_str: currentLocalStr,
        last_seen_epoch: currentEpoch,
        last_seen_str: currentLocalStr,
        seen_count: 1,

        // FIX: Retain raw frame footprint history data for reverse investigation bounds
        raw_data_hex: pkt.raw_data_hex 
    };

    if (pkt.wps_attributes) {
        apDatabase[mac].wps_attributes = pkt.wps_attributes;
    }
} else {
    if (pkt.ssid && pkt.ssid !== "<HIDDEN NETWORK>") {
        apDatabase[mac].ssid = pkt.ssid;
    }

    apDatabase[mac].encryption = pkt.encryption;
    apDatabase[mac].wps_status = pkt.wps_status;

    if (pkt.wps_attributes) {
        apDatabase[mac].wps_attributes = pkt.wps_attributes;
    } else if (pkt.wps_status === "DISABLED") {
        delete apDatabase[mac].wps_attributes;
    }

    apDatabase[mac].channel = pkt.channel;
    apDatabase[mac].rssi_latest = pkt.rssi;
    apDatabase[mac].cpu_temperature_latest_c = pkt.cpu_temperature_c;
    apDatabase[mac].tsf_microseconds_latest = pkt.tsf_microseconds;
    apDatabase[mac].ap_last_reboot_time = pkt.ap_last_reboot_time;
    apDatabase[mac].ap_uptime_compact = pkt.ap_uptime_compact;
    apDatabase[mac].packet_length_bytes = pkt.packet_length_bytes;

    apDatabase[mac].last_seen_epoch = currentEpoch;
    apDatabase[mac].last_seen_str = currentLocalStr;
    apDatabase[mac].seen_count += 1;

    // FIX: Keep the most recent frame string cached for diagnostic parsing
    apDatabase[mac].raw_data_hex = pkt.raw_data_hex; 
}

flow.set('apDatabase', apDatabase);
msg.payload = apDatabase;

return msg;

const apDatabase    = flow.get('apDatabase') || {};
const droneDatabase = flow.get('droneDatabase') || {};

const apList    = Object.values(apDatabase);
const droneList = Object.values(droneDatabase);

apList.sort((a, b) => b.rssi_latest - a.rssi_latest);
droneList.sort((a, b) => b.rssi - a.rssi);

msg.payload = {
    aps: apList,
