const pkt = msg.payload;
const rawHex = pkt.raw_data_hex;

// Safety check: Ensure raw hex data exists and contains an element body
if (!rawHex || rawHex.length <= 72) return null;

let isUAV = false;
let droneSerial = "UNKNOWN_SERIAL";
let droneLat = null;
let droneLon = null;
let droneAltBaro = null;
let droneAltGeo = null;
let droneSpeed = null;
let droneHeading = null;
let pilotLat = null;
let pilotLon = null;
let pilotAlt = null;

let idx = 72; // Start parsing immediately at the Tagged Parameter data index

while (idx < rawHex.length - 4) {
    let tagId  = parseInt(rawHex.substring(idx, idx + 2), 16);
    let tagLen = parseInt(rawHex.substring(idx + 2, idx + 4), 16); 
    idx += 4; 

    let hexLen = tagLen * 2; 
    if (idx + hexLen > rawHex.length) break; 

    let tagData = rawHex.substring(idx, idx + hexLen);

    // Validate the ASD-STAN / Open Drone ID OUI unique hardware identifier header (FA:0B:BC)
    if (tagId === 221 && tagData.toUpperCase().startsWith("FA0BBC")) {
        isUAV = true;

        // Skip the 3-byte OUI Header (6 hex chars) to reach the sub-message blocks
        let msgIdx = 6;

        // Loop through the 25-byte (50 hex characters) structured ODID message blocks
        while (msgIdx <= tagData.length - 50) {
            let subMsg = tagData.substring(msgIdx, msgIdx + 50);
            let msgType = parseInt(subMsg.substring(0, 2), 16) >> 4; // High 4 bits identify the message type

            // --- Type 0: Basic ID Message (Serial / Registration) ---
            if (msgType === 0) {
                let idType = parseInt(subMsg.substring(2, 4), 16) & 0x0F;
                let serialStr = "";
                for (let i = 4; i < 44; i += 2) {
                    let charCode = parseInt(subMsg.substring(i, i + 2), 16);
                    if (charCode >= 32 && charCode <= 126) serialStr += String.fromCharCode(charCode);
                }
                if (serialStr.trim().length > 0) droneSerial = serialStr.trim();
            }

            // --- Type 1: Location Message (Telemetry Data) ---
            else if (msgType === 1) {
                let rawHeading = parseInt(subMsg.substring(4, 6), 16);
                if (rawHeading !== 255) droneHeading = rawHeading * 0.5;

                let rawSpeed = parseInt(subMsg.substring(6, 8), 16);
                if (rawSpeed !== 255) droneSpeed = (rawSpeed * 0.25 * 3.6).toFixed(1); // Converted to km/h

                let rawLat = parseInt(subMsg.substring(8, 16), 16);
                if (rawLat & 0x80000000) rawLat -= 0x100000000; // Handle signed negative numbers
                if (rawLat !== 0x7FFFFFFF && rawLat !== 0) droneLat = rawLat / 10000000.0;

                let rawLon = parseInt(subMsg.substring(16, 24), 16);
                if (rawLon & 0x80000000) rawLon -= 0x100000000;
                if (rawLon !== 0x7FFFFFFF && rawLon !== 0) droneLon = rawLon / 10000000.0;

                let rawBaro = parseInt(subMsg.substring(24, 28), 16);
                if (rawBaro !== 0xFFFF) droneAltBaro = (rawBaro * 0.5) - 1000;

                let rawGeo = parseInt(subMsg.substring(28, 32), 16);
                if (rawGeo !== 0xFFFF) droneAltGeo = (rawGeo * 0.5) - 1000;
            }

            // --- Type 4: System Message (Pilot Operator Ground Station) ---
            else if (msgType === 4) {
                let rawPilotLat = parseInt(subMsg.substring(2, 10), 16);
                if (rawPilotLat & 0x80000000) rawPilotLat -= 0x100000000;
                if (rawPilotLat !== 0x7FFFFFFF && rawPilotLat !== 0) pilotLat = rawPilotLat / 10000000.0;

                let rawPilotLon = parseInt(subMsg.substring(10, 18), 16);
                if (rawPilotLon & 0x80000000) rawPilotLon -= 0x100000000;
                if (rawPilotLon !== 0x7FFFFFFF && rawPilotLon !== 0) pilotLon = rawPilotLon / 10000000.0;

                let rawPilotAlt = parseInt(subMsg.substring(18, 22), 16);
                if (rawPilotAlt !== 0xFFFF) pilotAlt = (rawPilotAlt * 0.5) - 1000;
            }

            msgIdx += 50; 
        }
        break;
    }
    idx += hexLen; 
}

// CRITICAL FILTER: Terminate flow thread instantly if this is a normal home base station
if (!isUAV) return null;

// Overwrite payload with clean, highly explicit UAV avionics parameters mapping
msg.payload = {
    timestamp: pkt.timestamp,
    time_local: new Date(pkt.timestamp * 1000).toLocaleString(),
    mac_address: pkt.mac_source,
    channel: pkt.channel,
    rssi: pkt.rssi,
    drone_serial_id: droneSerial,
    telemetry: {
        drone_latitude: droneLat,
        drone_longitude: droneLon,
        altitude_barometric_m: droneAltBaro,
        altitude_gps_geodetic_m: droneAltGeo,
        speed_kmh: droneSpeed ? parseFloat(droneSpeed) : null,
        heading_degrees: droneHeading
    },
    pilot_station: {
        pilot_latitude: pilotLat,
        pilot_longitude: pilotLon,
        pilot_altitude_m: pilotAlt
    },
    signal_status: pkt.rssi > -60 ? "CLOSE_PROXIMITY" : "DISTANT_AIRSPACE",

    // Locked structural parameter update for diagnostic extraction investigation passes
    raw_data_hex: rawHex 
};

// Retrieve, update, and persist the drone tracking map cleanly inside flow context memory
let droneDatabase = flow.get('droneDatabase') || {};
const previousEntry = droneDatabase[pkt.mac_address];
msg.payload.seen_count = previousEntry ? previousEntry.seen_count + 1 : 1;
droneDatabase[pkt.mac_address] = msg.payload; 
flow.set('droneDatabase', droneDatabase);

return msg;

